/**
 * Differential runner (WP9 3.11.6 Layer 3). Same source compiled against develop's and the branch's classpath.
 *
 * <pre>
 * java DiffRunner <corpus> <out.tsv> <memory|native|lmdb> [phases=cold,seq,postcold] [caseRegex]
 * </pre>
 *
 * Phases per case: cold = fresh store per query; seq = one store: seq1, seq2 (warm), write1 + write2 (after the
 * case's update), reopen (native/lmdb: shutdown + reopen same dir); postcold = fresh store, load, update, query.
 * Output: case \t query \t store \t phase \t canonical-result \t detail \t millis
 */
public class DiffRunner {

	record Q(int idx, String flags, String text) {
	}

	record Case(String id, String data, List<Q> queries, String update) {
	}

	static final Set<Repository> OPEN = ConcurrentHashMap.newKeySet();
	static final ExecutorService EXEC = Executors.newCachedThreadPool(r -> {
		Thread t = new Thread(r, "diff-query");
		t.setDaemon(true);
		return t;
	});
	static final long HARD_TIMEOUT_SECONDS = Long.getLong("diff.hardTimeout", 60);
	static final long CASE_TIMEOUT_SECONDS = Long.getLong("diff.caseTimeout", 300);

	/** Thrown after a hard timeout: the query thread may still hold the store, so the case's store is abandoned. */
	static final class Abandon extends RuntimeException {
		Abandon(String msg) {
			super(msg, null, false, false);
		}
	}

	public static void main(String[] args) throws Exception {
		List<Case> cases = parse(Path.of(args[0]));
		String kind = args[2];
		Set<String> phases = Set.of((args.length > 3 ? args[3] : "cold,seq,postcold").split(","));
		Pattern filter = args.length > 4 ? Pattern.compile(args[4]) : null;
		Path base = Path.of(System.getProperty("diff.tmp", System.getProperty("java.io.tmpdir")));
		Files.createDirectories(base);
		Runtime.getRuntime().addShutdownHook(new Thread(() -> OPEN.forEach(r -> {
			try {
				r.shutDown();
			} catch (Throwable ignored) {
			}
		})));
		try (PrintWriter out = new PrintWriter(Files.newBufferedWriter(Path.of(args[1]), StandardCharsets.UTF_8))) {
			int n = 0;
			for (Case c : cases) {
				if (filter != null && !filter.matcher(c.id()).find()) {
					continue;
				}
				java.io.StringWriter buf = new java.io.StringWriter();
				PrintWriter caseOut = new PrintWriter(buf);
				Future<?> worker = EXEC.submit(() -> {
					runCase(caseOut, c, kind, phases, base);
					return null;
				});
				try {
					worker.get(CASE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
				} catch (TimeoutException e) {
					// the worker may be stuck in planning/evaluation or in close(); leave it and its store behind
					caseOut.println(c.id() + "\t-\t" + kind + "\tabandon\tABANDONED\tcase-timeout\t0");
					System.err.println("[diff] abandoned " + c.id());
				} catch (java.util.concurrent.ExecutionException e) {
					caseOut.println(c.id() + "\t-\t" + kind + "\tcase\tCASE-ERROR " + e.getCause().getClass().getSimpleName()
							+ "\t" + oneLine(String.valueOf(e.getCause().getMessage())) + "\t0");
				}
				caseOut.flush();
				synchronized (buf) {
					out.print(buf.toString());
				}
				out.flush();
				if (++n % 25 == 0) {
					System.err.println("[diff] " + kind + " cases=" + n);
				}
			}
		}
		EXEC.shutdownNow();
		System.exit(0);
	}

	static void runCase(PrintWriter out, Case c, String kind, Set<String> phases, Path base) throws Exception {
		{
			{
				if (phases.contains("cold")) {
					for (Q q : c.queries()) {
						Path dir = Files.createTempDirectory(base, "cold");
						Repository repo = open(kind, dir);
						try (RepositoryConnection con = repo.getConnection()) {
							load(con, c.data());
							emit(out, c, q, kind, "cold", con);
						} finally {
							close(repo, dir);
						}
					}
				}
				if (phases.contains("seq")) {
					Path dir = Files.createTempDirectory(base, "seq");
					Repository repo = open(kind, dir);
					try {
						try (RepositoryConnection con = repo.getConnection()) {
							load(con, c.data());
							for (Q q : c.queries()) {
								emit(out, c, q, kind, "seq1", con);
							}
							for (Q q : c.queries()) {
								emit(out, c, q, kind, "seq2", con);
							}
							String u = update(con, c.update());
							out.println(c.id() + "\t-\t" + kind + "\tupdate\t" + u + "\t\t0");
							for (Q q : c.queries()) {
								emit(out, c, q, kind, "write1", con);
							}
							for (Q q : c.queries()) {
								emit(out, c, q, kind, "write2", con);
							}
						}
						if (!kind.startsWith("mem")) {
							repo.shutDown();
							OPEN.remove(repo);
							Repository reopened = null;
							try {
								reopened = open(kind, dir);
							} catch (Throwable t) {
								out.println(c.id() + "\t-\t" + kind + "\treopen\tREOPEN-ERROR " + t.getClass().getSimpleName()
										+ "\t" + oneLine(String.valueOf(rootCause(t).getMessage())) + "\t0");
							}
							if (reopened != null) {
								repo = reopened;
								try (RepositoryConnection con = repo.getConnection()) {
									for (Q q : c.queries()) {
										emit(out, c, q, kind, "reopen", con);
									}
								}
							}
						}
					} finally {
						close(repo, dir);
					}
				}
				if (phases.contains("postcold")) {
					for (Q q : c.queries()) {
						Path dir = Files.createTempDirectory(base, "post");
						Repository repo = open(kind, dir);
						try (RepositoryConnection con = repo.getConnection()) {
							load(con, c.data());
							update(con, c.update());
							emit(out, c, q, kind, "postcold", con);
						} finally {
							close(repo, dir);
						}
					}
				}
			}
		}
	}

	static Repository open(String kind, Path dir) {
		Sail sail = switch (kind) {
		case "memory" -> new MemoryStore();
		case "memhint" -> {
			try {
				yield (Sail) Class.forName("org.eclipse.rdf4j.sail.memory.ExistsHintFactory").getMethod("store").invoke(null);
			} catch (ReflectiveOperationException e) {
				throw new IllegalStateException(e);
			}
		}
		case "native" -> new NativeStore(dir.toFile());
		case "lmdb" -> System.getProperty("diff.lmdbIndexes") == null ? new LmdbStore(dir.toFile())
				: new LmdbStore(dir.toFile(),
						new org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig(System.getProperty("diff.lmdbIndexes")));
		default -> throw new IllegalArgumentException(kind);
		};
		Repository repo = new SailRepository(sail);
		repo.init();
		OPEN.add(repo);
		return repo;
	}

	static Throwable rootCause(Throwable t) {
		while (t.getCause() != null && t.getCause() != t) {
			t = t.getCause();
		}
		return t;
	}

	static void close(Repository repo, Path dir) throws Exception {
		if (!OPEN.contains(repo)) {
			return; // abandoned after a hard timeout
		}
		try {
			repo.shutDown();
		} finally {
			OPEN.remove(repo);
			try (Stream<Path> walk = Files.walk(dir)) {
				walk.sorted(Comparator.reverseOrder()).map(Path::toFile).forEach(File::delete);
			}
		}
	}

	static void load(RepositoryConnection con, String trig) throws Exception {
		con.begin();
		con.add(new StringReader(trig), "http://ex.org/", RDFFormat.TRIG);
		con.commit();
	}

	static String update(RepositoryConnection con, String update) {
		try {
			con.begin();
			con.prepareUpdate(QueryLanguage.SPARQL, update).execute();
			con.commit();
			return "OK";
		} catch (Throwable t) {
			try {
				con.rollback();
			} catch (Throwable ignored) {
			}
			return "UPDATE-ERROR " + t.getClass().getSimpleName() + ": " + oneLine(t.getMessage());
		}
	}

	static void emit(PrintWriter out, Case c, Q q, String kind, String phase, RepositoryConnection con) {
		long t0 = System.nanoTime();
		out.flush();
		String[] res = run(con, q.text());
		long ms = (System.nanoTime() - t0) / 1_000_000;
		out.println(c.id() + "\t" + q.idx() + "\t" + kind + "\t" + phase + "\t" + res[0] + "\t" + res[1] + "\t" + ms);
	}

	static String[] run(RepositoryConnection con, String text) {
		try {
			Query query = con.prepareQuery(QueryLanguage.SPARQL, text);
			query.setMaxExecutionTime(30);
			if (query instanceof TupleQuery tq) {
				List<String> rows = new ArrayList<>();
				List<String> names;
				try (TupleQueryResult r = tq.evaluate()) {
					names = new ArrayList<>(r.getBindingNames());
					while (r.hasNext()) {
						BindingSet bs = r.next();
						List<String> cells = new ArrayList<>();
						for (Binding b : bs) {
							cells.add(b.getName() + "=" + value(b.getValue()));
						}
						Collections.sort(cells);
						rows.add(String.join(" | ", cells));
					}
				}
				Collections.sort(rows);
				Collections.sort(names);
				return new String[] { "ROWS " + rows.size() + " " + names + " :: " + String.join(" ;; ", rows), "" };
			}
			if (query instanceof BooleanQuery bq) {
				return new String[] { "BOOL " + bq.evaluate(), "" };
			}
			if (query instanceof GraphQuery gq) {
				List<String> lines = new ArrayList<>();
				try (GraphQueryResult r = gq.evaluate()) {
					for (Statement st : r) {
						lines.add(value(st.getSubject()) + " " + value(st.getPredicate()) + " " + value(st.getObject()));
					}
				}
				Collections.sort(lines);
				return new String[] { "GRAPH " + lines.size() + " :: " + String.join(" ;; ", lines), "" };
			}
			return new String[] { "ERROR unknown-query-type", query.getClass().getName() };
		} catch (Throwable t) {
			return new String[] { "ERROR " + t.getClass().getSimpleName(), oneLine(t.getMessage()) };
		}
	}

	static String value(Value v) {
		if (v == null) {
			return "UNDEF";
		}
		if (v instanceof BNode) {
			return "_:b";
		}
		return NTriplesUtil.toNTriplesString(v);
	}

	static String oneLine(String s) {
		if (s == null) {
			return "";
		}
		s = s.replace('\t', ' ').replace('\r', ' ');
		int nl = s.indexOf('\n');
		if (nl >= 0) {
			s = s.substring(0, nl);
		}
		return s.length() > 240 ? s.substring(0, 240) : s;
	}

	static List<Case> parse(Path corpus) throws Exception {
		List<Case> cases = new ArrayList<>();
		String id = null;
		StringBuilder data = null;
		StringBuilder cur = null;
		String section = null;
		List<Q> qs = null;
		int qidx = -1;
		String qflags = "";
		String upd = null;
		for (String line : Files.readAllLines(corpus, StandardCharsets.UTF_8)) {
			if (line.startsWith("### ")) {
				// close previous section
				if ("QUERY".equals(section)) {
					qs.add(new Q(qidx, qflags, cur.toString()));
				} else if ("UPDATE".equals(section)) {
					upd = cur.toString();
				}
				String[] p = line.substring(4).split(" ", 3);
				section = p[0];
				cur = new StringBuilder();
				switch (section) {
				case "CASE" -> {
					id = p[1];
					qs = new ArrayList<>();
					upd = null;
				}
				case "DATA" -> data = cur;
				case "QUERY" -> {
					qidx = Integer.parseInt(p[1]);
					qflags = p.length > 2 ? p[2] : "";
				}
				case "END" -> cases.add(new Case(id, data.toString(), qs, upd));
				default -> {
				}
				}
				continue;
			}
			cur.append(line).append('\n');
		}
		return cases;
	}
}
